DROP POLICY IF EXISTS "Admins and Operations manage company asset groups" ON public.asset_groups;
CREATE POLICY "Staff manage company asset groups" ON public.asset_groups FOR ALL TO authenticated
USING ((has_role(auth.uid(),'admin'::app_role) OR is_operations(auth.uid()) OR has_role(auth.uid(),'hr'::app_role)) AND (is_super_admin(auth.uid()) OR company_id IN (SELECT user_company_ids(auth.uid()))))
WITH CHECK ((has_role(auth.uid(),'admin'::app_role) OR is_operations(auth.uid()) OR has_role(auth.uid(),'hr'::app_role)) AND (is_super_admin(auth.uid()) OR company_id IN (SELECT user_company_ids(auth.uid()))));